/* ====== LÓGICA ====== */
const $=s=>document.querySelector(s),cop=n=>"$"+n.toLocaleString("es-CO");
let cart={},pend={},fg="todos",fb="todas";const DESC=RECARGO_1-RECARGO_PROMO;const pq=id=>pend[id]||1;const ADM=location.hash=="#precios";
try{cart=JSON.parse(localStorage.getItem("cart")||"{}")}catch(e){}
const total=()=>Object.values(cart).reduce((a,b)=>a+b,0);
// Precio final unitario: mayorista + $50.000 (1–2 unidades) o + $30.000 (3+).
const unit=(p,q=total())=>p.base+(q>=MIN_PROMO?RECARGO_PROMO:RECARGO_1);
const save=()=>{try{localStorage.setItem("cart",JSON.stringify(cart))}catch(e){}};
$("#heroimg").src=IMG["j8"];
function grid(){
 const l=P.filter(p=>(fg=="todos"||p.g==fg)&&(fb=="todas"||p.brand==fb));
 $("#grid").innerHTML=l.length?l.map(p=>`<article class="card"><div class="ph${p.g=="pareja"?" sq":""}"><img src="${p.img}" alt="Reloj ${p.brand} ${p.name}" loading="lazy"></div><div class="bd"><span class="brand">${p.brand}</span>${p.id==="m16"?"<small class=\"code\">Código: MF16</small>":p.id==="m17"?"<small class=\"code\">Código: MF17</small>":""}<h3>${p.name}</h3>
 <details><summary>Características</summary><ul>${p.f.map(x=>`<li>${x}</li>`).join("")}</ul></details>
 <div class="price" data-p="${p.id}"></div><div class="hint" data-h="${p.id}"></div><div class="sub" data-a="${p.id}"></div>
 <div class="pick"><div class="ask">¿Cuántos quieres llevar?</div><div class="row"><div class="qty"><button data-q="-1" data-id="${p.id}" aria-label="Menos">−</button><span data-n="${p.id}">1</span><button data-q="1" data-id="${p.id}" aria-label="Más">+</button></div><button class="add" data-id="${p.id}">Agregar</button></div></div></div></article>`).join(""):`<div class="empty">No hay relojes con esos filtros.</div>`;
}
function toast(m,gold){const d=document.createElement("div");d.className="toast"+(gold?" gold":"");d.textContent=m;$("#toasts").append(d);setTimeout(()=>d.remove(),3200)}
function cards(){
 const n0=total();
 P.forEach(p=>{const pe=$(`[data-p="${p.id}"]`);if(!pe)return;const q=pq(p.id),n=n0+q,h=$(`[data-h="${p.id}"]`);
  pe.textContent=cop(unit(p,n))+" c/u";
  pe.classList.remove("price-pop"); void pe.offsetWidth; pe.classList.add("price-pop");
  if(ADM)$(`[data-a="${p.id}"]`).textContent=`VERIFICAR · ${p.id} · chat: ${cop(p.base)}`;$(`[data-n="${p.id}"]`).textContent=q;
  if(n>=MIN_PROMO){h.className="hint ok";h.textContent=`Promo activa: ${q} × ${cop(unit(p,n))} = ${cop(q*unit(p,n))}`}
  else{h.className="hint";h.textContent=`Con ${MIN_PROMO-n} más en total, cada reloj baja ${cop(DESC)}`}});
}
function draw(){
 const n=total(),ids=Object.keys(cart).filter(k=>cart[k]>0);
 $("#cnt").textContent=n;
 $("#cnt").classList.remove("count-pop"); void $("#cnt").offsetWidth; $("#cnt").classList.add("count-pop");
 $("#items").innerHTML=ids.length?ids.map(id=>{const p=P.find(x=>x.id==id),q=cart[id];return `<div class="it"><img src="${p.img}" alt=""><div><b>${p.brand} · ${p.name}</b><small>${cop(unit(p))} c/u</small><div class="qty"><button data-d="-1" data-id="${id}" aria-label="Quitar uno">−</button><span>${q}</span><button data-d="1" data-id="${id}" aria-label="Agregar uno">+</button></div></div><b>${cop(unit(p)*q)}</b></div>`}).join(""):`<p style="color:var(--mute);padding:20px 0">Tu carrito está vacío. Elige cuántos relojes quieres y toca Agregar.</p>`;
 const tip=$("#tip"),msg=n>=MIN_PROMO?`Promo activa: cada reloj te sale ${cop(DESC)} más barato. Llevas ${n}.`:n?`Llevas ${n}. Agrega ${MIN_PROMO-n} más y cada reloj baja ${cop(DESC)}.`:`Llevando ${MIN_PROMO} o más, cada reloj baja ${cop(DESC)}.`;
 tip.className="tip"+(n>=MIN_PROMO?" ok":"");tip.textContent=msg;
 $("#pg").style.width=Math.min(100,n/MIN_PROMO*100)+"%";
 $("#strip").textContent=n>=MIN_PROMO?`Promo activa: pagas ${cop(DESC)} menos por reloj`:n?`Llevas ${n} de ${MIN_PROMO}. Te faltan ${MIN_PROMO-n} para bajar ${cop(DESC)} por reloj`:`Llevando ${MIN_PROMO} o más relojes, cada uno baja ${cop(DESC)}`;
 const t=ids.reduce((a,id)=>a+unit(P.find(x=>x.id==id))*cart[id],0);
 $("#tot").textContent=cop(t);$("#wa").disabled=!n;cards();
}
function set(id,d){const before=total();cart[id]=Math.max(0,(cart[id]||0)+d);if(!cart[id])delete cart[id];save();draw();
 const after=total(),p=P.find(x=>x.id==id);
 if(before<MIN_PROMO&&after>=MIN_PROMO)toast(`¡Promo activada! Cada reloj baja ${cop(DESC)}`,true);
 else if(before>=MIN_PROMO&&after<MIN_PROMO)toast(`Ya no tienes la promo. Agrega ${MIN_PROMO-after} más para recuperarla`);
 else if(d<0&&!cart[id])toast(`Quitaste ${p.brand} ${p.name} del carrito`)}
const open=v=>{$("#dr").classList.toggle("on",v);$("#ov").classList.toggle("on",v);$("#dr").setAttribute("aria-hidden",!v)};
$("#grid").onclick=e=>{const s=e.target.closest("[data-q]");if(s){const id=s.dataset.id;pend[id]=Math.min(20,Math.max(1,pq(id)+ +s.dataset.q));cards();return}
 const b=e.target.closest(".add");if(b){const id=b.dataset.id,q=pq(id),p=P.find(x=>x.id==id);set(id,q);pend[id]=1;cards();toast(`Agregaste ${q} × ${p.brand} ${p.name} al carrito`)}};
$("#items").onclick=e=>{const b=e.target.closest("[data-d]");if(b)set(b.dataset.id,+b.dataset.d)};
$("#open").onclick=()=>open(true);$("#close").onclick=$("#ov").onclick=()=>open(false);
document.onkeydown=e=>{if(e.key=="Escape")open(false)};
function seg(sel,key){$(sel).onclick=e=>{const b=e.target.closest("button");if(!b)return;[...$(sel).children].forEach(c=>c.setAttribute("aria-pressed",c==b));key(b);grid()}}
seg("#fg",b=>fg=b.dataset.g);seg("#fb",b=>fb=b.dataset.b);
$("#wa").onclick=()=>{
 if(!$("#nm").value.trim()||!$("#ct").value.trim()){const tp=$("#tip");tp.className="tip err";tp.textContent="Escribe tu nombre y tu ciudad para enviar el pedido.";($("#nm").value.trim()?$("#ct"):$("#nm")).focus();toast("Falta tu nombre o ciudad");return}
 toast("Abriendo WhatsApp con tu pedido…",true);
 const ids=Object.keys(cart),n=total();let t=0;
 const lines=ids.map(id=>{const p=P.find(x=>x.id==id),s=unit(p)*cart[id];t+=s;return `• ${cart[id]} x ${p.brand} ${p.name} = ${cop(s)}`});
 const msg=`Hola, quiero hacer este pedido:\n${lines.join("\n")}\n\nTotal: ${cop(t)} (${n} relojes)\nNombre: ${$("#nm").value||"-"}\nEntrega: ${$("#ct").value||"-"}`;
 window.open("https://wa.me/"+WHATSAPP+"?text="+encodeURIComponent(msg),"_blank");
};
grid();draw();
